        char _zp_buf[128];
        snprintf(_zp_buf, sizeof(_zp_buf), "List slice: [%lu, %lu) out of bounds (length %lu)", (unsigned long)_from, (unsigned long)_to, (unsigned long)_this->length);
        z_panic(_zp_buf);
